import { createPinia, setActivePinia } from "pinia";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { HYDRATION_TIMEOUT_MS } from "@/lib/runtime/constants";
import { useRuntimeStore } from "@/stores/runtime";
const m = vi.hoisted(() => ({ inv: vi.fn(), lis: vi.fn(), tauri: vi.fn() }));
vi.mock("@/lib/tauri", () => ({ safeInvoke: m.inv, safeListen: m.lis, isTauriAvailable: m.tauri }));
beforeEach(() => {
  vi.useFakeTimers(); window.localStorage.clear(); setActivePinia(createPinia());
  m.lis.mockResolvedValue(() => {}); m.tauri.mockReturnValue(true);
  m.inv.mockImplementation((c: string) => c === "list_sessions"
    ? Promise.resolve([{ conversationId: "s1", title: "t", summary: "s", turnCount: 1, lastReferencedFile: null, updatedAtMs: 1, workspaceId: null }])
    : new Promise<never>(() => {}));
});
afterEach(() => { vi.useRealTimers(); });
it("stale timeout rollback wipes state written after the 3500ms watchdog and clears a foreign sessionOperation lock", async () => {
  const store = useRuntimeStore();
  void store.initializeSessions();
  await vi.advanceTimersByTimeAsync(4000);
  expect(store.sessionOperation).toBeNull();
  store.sessionId = "user-created-session"; store.phase = "ready";
  store.messages = [{ id: "m1", turnId: "t1", role: "user", content: "窗口内输入" }] as never;
  store.sessionOperation = "deleting";
  await vi.advanceTimersByTimeAsync(HYDRATION_TIMEOUT_MS + 1000);
  expect(store.sessionId).toBe("local-dev-session");
  expect(store.messages).toHaveLength(0);
  expect(store.sessionOperation).toBeNull();
});
EOF
